namespace Lifestone.Client.Options;

public static partial class OptionCatalog
{
    /// <summary>
    /// The hunt loop (M4 1.2 s4a), read by the headless host's hunt scenario and the game's hunt leg (<c>--login-check=hunt</c>, HuntLegRunner); parsed by src/Lifestone.Client/Session/Scenarios/HuntOptions.cs (<c>HuntOptions.FromArguments</c>).
    /// </summary>
    public static OptionGroup Hunt() => new("Hunt loop", "main scene and headless host",
    [
        new("--hunt-kills", "N", "How many kills end the hunt loop (1 to 1000, default 1): Holtburg Hunter fights the creatures of the Low B belt south-west of Holtburg until the Nth 0x01AD kill notice. A bad value fails the headless run."),
        new("--hunt-seconds", "S", "The most session-clock seconds the hunt loop may take from its first teleport to the belt (default 300); past it the hunt fails loudly with the kills so far, goes back to Holtburg and logs off."),
        new("--hunt-weapon", "melee|missile", "The weapon the hunt fights with (default melee): melee swings the Mace the fighter build wields (one Attack per sequence; ACE walks the player in and repeats the swing), missile puts the Mace in the pack, wields the Shortbow and the Arrows, enters the missile combat mode and shoots (one MissileAttack per sequence, targets within 35 m); both restore the Mace at the end."),
        new("--hunt-ground", "belt|forest", "The ground the hunt goes to (default belt; M4 3.1): belt is the Low B belt south-west of Holtburg (creatures of levels 8 to 20, ten cells 4.6 to 5 map units out), forest is the Low North Forest Mix west of Holtburg (the 0x9FB* landblocks, 7.7 to 9.2 map units out; creatures of levels 30 to 40 by the table of their weenie class ids, since the level is not on the wire). Only dry, walkable cells are used (HuntGroundDatTests). A bad value fails the headless run."),
        new("--hunt-open-corpse", "on|off", "Whether the hunt opens the corpse of its kill (default on): within 5 s of the kill notice the first 'Corpse of <target>' near the target's last position is opened (Use, in the combat stance: ACE accepts it), its contents are logged, and it is closed once the loot (--loot) is done and the attack's last 01A7 is in. The leg prints corpses_opened= and corpse_items=. off restores M4 1.2's hunt, which leaves the corpse alone."),
        new("--loot", "on|off", "Whether the hunt loots the corpse it opened (default on; M4 2.2): after the contents are listed the hunt picks up, one at a time in the corpse's order, every item the loot rule takes, and closes the corpse once the loot is done and the attack's last 01A7 is in. off restores M4 2.1's hunt: open, list, close, take nothing. It needs --hunt-open-corpse on (no corpse is opened without it, so nothing is looted). The leg prints looted=, loot_skipped= and loot_frame_max_ms= (report-only). A bad value fails the headless run."),
        new("--loot-types", "shop|all|HEX", "The item types the loot rule takes (default shop): shop is the type mask of the Holtburg shopkeeper Renald the Elder (0x480467A7: weapons, armour, clothing, food, misc, containers, keys, writables and the like; no jewelry, gems, money or spell components), all takes any type, or a non-zero hex mask of ItemType bits (0x prefix optional). The mask is the shard's database value (confirmed against Renald's own 0062 in M4 3.2's capture, m4-loot-rules-shop-mask); an open vendor's 0062 mask replaces it when one is read."),
        new("--loot-min-value", "N", "The least Value of an item the loot rule takes (0 to 1000000, default 1: an item worth nothing is left); the greatest is the shopkeeper's 1000000. A bad value fails the headless run."),
        new("--loot-max-burden", "PCT", "How much of the carrying capacity the burden may reach with the item taken, in percent (1 to 300, default 100, the inventory page's load); an item that would carry the burden over it is left. A bad value fails the headless run."),
        new("--heal", "on|off", "Whether the hunt recovers between its kills and before its first fight (default on; M4 3.1): under --heal-below percent of the maximum health the hunt uses a Handy Healing Kit on itself while the kit's estimated chance (ACE's formula, from the Healing skill and the missing health) is at least --heal-chance, else a Potion of Healing (25 points, never at a full vital), else (with no potion) the kit as the last resort down to --heal-floor-chance, else it waits for regeneration for up to 300 s and then fails loudly. off runs no recovery (the retreat at 30% health still ends a fight). There is no heal during a fight."),
        new("--heal-below", "PCT", "The share of the maximum health, in percent, under which a recovery starts (1 to 100, default 75): checked before the first fight and between kills, never during a fight. A bad value fails the headless run."),
        new("--heal-until", "PCT", "The share, in percent, a started recovery heals to (1 to 100, default 90, not under --heal-below). A bad value fails the headless run."),
        new("--heal-chance", "P", "The least estimated chance (0 to 1, default 0.7) at which the Handy Healing Kit is used: a kit used under about 45% health mostly burns uses for nothing (ACE rolls 1/(1+e^(-0.03 (eff-diff))), capture 3.1 C1), so under it a potion is used. Two lost rolls in a row also switch to a potion. A bad value fails the headless run."),
        new("--heal-floor-chance", "P", "The least estimated chance (0 to 1, default 0.3) at which the Handy Healing Kit is used as the last resort (M4 3.1 fix): with no potion to drink and the kit's chance under --heal-chance, a kit at or over this is used before the regeneration wait (regeneration is nearly nothing, capture 3.1 C1, and the wait ends in a failure); the log says it is the last resort. Under it the recovery waits as before. A bad value fails the headless run."),
        new("--sell", "on|off", "Whether the hunt sells its loot at the loop's end (default on; M4 3.2): back in Holtburg the hunter goes to Shopkeeper Renald the Elder (place loc into his shop, cell 0xA9B40141, within his 5 m use radius; TODO(m4-vendor-approach) names the walk through the door that is not built), opens him and sells every held item his 0062 mask takes (Value at least 1) that is not worn, not a healing kit or restorative, not the Mace, Shortbow or Arrows, not pyreals and not a container, whole stacks, then returns to Holtburg and logs off. A failed sale never fails the hunt: the leg prints sold= and pyreals=<delta> and the detail line says sell=failed:<reason>. off keeps the loot."),
        new("--buy-kits", "N", "How many Handy Healing Kits the hunt keeps (0 to 100, default 2; 0 is off; M4 3.2, D14): with fewer held at the loop's end the hunter goes to Thelnoth Cort the Healer (cell 0xA9B40111, 3 m use radius), opens him and buys the missing kits from his 0062 at the predicted price; the leg prints bought=<n>. The fighter build is unchanged (FighterKit); the purchase only refills the loop's kits. A bad value fails the headless run."),
        new("--appraise-loot", "on|off", "Whether the hunt identifies each looted item once after its pick-up (default on; M4 3.2): one Identify (0x00C8) per item, answered in a few milliseconds by ACE with no busy hold; the leg prints appraised=<n>, the answers that succeeded. off identifies nothing (appraised=0)."),
    ], OptionScenes.Main | OptionScenes.Headless);
}
